import torch
from torch import nn

class Cascade(nn.Module):
    def __init__(self, num_classes):
        super().__init__()
        self.coarse = build_registered_model('cnn', {'hidden_dim': 16, 'depth': 1})
        self.detail = build_registered_model('gru', {'hidden_dim': 32})
        self.refine = nn.Linear(2 * num_classes, num_classes)

    def forward(self, x):
        coarse = self.coarse(x)
        detail = self.detail(x)
        correction = self.refine(torch.cat([coarse, detail], dim=1))
        return coarse + correction

def build_model(input_dim, num_classes, params):
    return Cascade(num_classes)
